-- LOCAL ONLY demo seed (never applied to the remote project: auth.users is shared between apps).
-- Mirrors the in-app demo world (docs/implementation/fase-05-modo-demo.md).
-- Local logins: customer@rutta.test, courier1@rutta.test, courier2@rutta.test (codes arrive in Mailpit, :54324).

-- ---------------------------------------------------------------- users
insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
  raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
  confirmation_token, recovery_token, email_change, email_change_token_new)
select '00000000-0000-0000-0000-000000000000', u.id::uuid, 'authenticated', 'authenticated', u.email, '', now(),
  '{"provider":"email","providers":["email"]}', '{}', now(), now(), '', '', '', ''
from (values
  ('a1000000-0000-4000-8000-000000000001', 'customer@rutta.test'),
  ('a2000000-0000-4000-8000-000000000001', 'courier1@rutta.test'),
  ('a2000000-0000-4000-8000-000000000002', 'courier2@rutta.test')
) as u (id, email)
on conflict (id) do nothing;

insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
select gen_random_uuid(), u.id::uuid, u.id,
  jsonb_build_object('sub', u.id, 'email', u.email, 'email_verified', true),
  'email', now(), now(), now()
from (values
  ('a1000000-0000-4000-8000-000000000001', 'customer@rutta.test'),
  ('a2000000-0000-4000-8000-000000000001', 'courier1@rutta.test'),
  ('a2000000-0000-4000-8000-000000000002', 'courier2@rutta.test')
) as u (id, email)
on conflict do nothing;

-- Profiles are inserted directly (as postgres) with their roles.
insert into rutta.profiles (id, full_name, role) values
  ('a1000000-0000-4000-8000-000000000001', 'Alex Rivera', 'customer'),
  ('a2000000-0000-4000-8000-000000000001', 'Carlos Méndez', 'courier'),
  ('a2000000-0000-4000-8000-000000000002', 'María López', 'courier');

