-- ---------------------------------------------------------------- orders (all from the customer)
insert into rutta.orders (code, customer_id, courier_id, status, pickup_name, pickup_address, pickup_lat, pickup_lng,
  dropoff_address, dropoff_lat, dropoff_lng, items, total_cents, route, route_distance_m, route_duration_s, created_at)
select o.code, 'a1000000-0000-4000-8000-000000000001', o.courier_id::uuid, o.status,
  r.pickup_name, r.pickup_address, r.pickup_lat, r.pickup_lng,
  r.dropoff_address, r.dropoff_lat, r.dropoff_lng, o.items::jsonb, o.total_cents,
  r.route, r.distance_m, r.duration_s, now() - make_interval(mins => o.created_mins)
from (values
  ('RT-1042', 'r1', 'in_transit', 'a2000000-0000-4000-8000-000000000001',
   '[{"name":"Flat white","quantity":2},{"name":"Butter croissant","quantity":1}]', 18500, 25),
  ('RT-1043', 'r2', 'picked_up', 'a2000000-0000-4000-8000-000000000002',
   '[{"name":"Ibuprofen 400 mg","quantity":1},{"name":"Electrolyte drink","quantity":2}]', 24900, 15),
  ('RT-1044', 'r3', 'assigned', 'a2000000-0000-4000-8000-000000000001',
   '[{"name":"Quinoa bowl","quantity":1},{"name":"Green juice","quantity":1}]', 21000, 9),
  ('RT-1045', 'r4', 'created', null,
   '[{"name":"Concha","quantity":6},{"name":"Café de olla","quantity":1}]', 13500, 2),
  ('RT-1038', 'r5', 'delivered', 'a2000000-0000-4000-8000-000000000001',
   '[{"name":"Vitamin C 1 g","quantity":1}]', 9900, 1490),
  ('RT-1036', 'r6', 'delivered', 'a2000000-0000-4000-8000-000000000002',
   '[{"name":"Salmon poke bowl","quantity":1}]', 23500, 2930),
  ('RT-1034', 'r4', 'cancelled', null,
   '[{"name":"Iced latte","quantity":2}]', 11000, 4330),
  ('RT-1033', 'r1', 'cancelled', 'a2000000-0000-4000-8000-000000000002',
   '[{"name":"Club sandwich","quantity":1}]', 15500, 5000)
) as o (code, route_key, status, courier_id, items, total_cents, created_mins)
join seed_routes r on r.key = o.route_key;

-- ---------------------------------------------------------------- status history
-- The trigger logged one event per order with now(); replace them with a realistic history.
delete from rutta.order_status_events where order_id in (select id from rutta.orders);

insert into rutta.order_status_events (order_id, status, changed_by, created_at)
select o.id, e.status,
  case when e.status in ('picked_up', 'in_transit', 'delivered') then o.courier_id end,
  now() - make_interval(mins => e.mins_ago)
from (values
  ('RT-1042', 'created', 25), ('RT-1042', 'assigned', 22), ('RT-1042', 'picked_up', 12), ('RT-1042', 'in_transit', 8),
  ('RT-1043', 'created', 15), ('RT-1043', 'assigned', 12), ('RT-1043', 'picked_up', 3),
  ('RT-1044', 'created', 9), ('RT-1044', 'assigned', 5),
  ('RT-1045', 'created', 2),
  ('RT-1038', 'created', 1490), ('RT-1038', 'assigned', 1487), ('RT-1038', 'picked_up', 1475),
  ('RT-1038', 'in_transit', 1472), ('RT-1038', 'delivered', 1456),
  ('RT-1036', 'created', 2930), ('RT-1036', 'assigned', 2926), ('RT-1036', 'picked_up', 2915),
  ('RT-1036', 'in_transit', 2911), ('RT-1036', 'delivered', 2890),
  ('RT-1034', 'created', 4330), ('RT-1034', 'cancelled', 4325),
  ('RT-1033', 'created', 5000), ('RT-1033', 'assigned', 4996), ('RT-1033', 'cancelled', 4990)
) as e (code, status, mins_ago)
join rutta.orders o on o.code = e.code;

-- ---------------------------------------------------------------- courier locations
-- courier1 on RT-1042 at 40 % of the route; courier2 on RT-1043 at the first point.
-- recorded_at is stamped by the trigger (now()), so ~30 s after a reset it already looks stale.
insert into rutta.courier_locations (courier_id, order_id, lat, lng, heading, speed_mps, accuracy_m)
select o.courier_id, o.id,
  (o.route -> (jsonb_array_length(o.route) * 4 / 10) ->> 1)::float8,
  (o.route -> (jsonb_array_length(o.route) * 4 / 10) ->> 0)::float8,
  90, 8.3, 10
from rutta.orders o where o.code = 'RT-1042';

insert into rutta.courier_locations (courier_id, order_id, lat, lng, heading, speed_mps, accuracy_m)
